function boardPoint(event,board=currentBoard()){const canvas=$('#boardCanvas'),rect=canvas.getBoundingClientRect(),zoom=board?.zoom||1;return {x:(event.clientX-rect.left)/zoom,y:(event.clientY-rect.top)/zoom}}
